parameters.prompt:
=You are a senior legal editor for common-law.ai.

Create a detailed article outline for:
- Topic: "{{ $('Select Approved Topic').item.json.title_idea }}"
- Primary Keyword: "{{ $('Select Approved Topic').item.json.primary_keyword }}"
- Jurisdiction: {{ $('Select Approved Topic').item.json.target_state }}
- Practice Area: {{ $('Select Approved Topic').item.json.practice_area }}

Verified legal sources available:
{{ JSON.stringify(($json.results || []).slice(0,3).map(r => ({case: r.caseName, url: r.absolute_url}))) }}

Return ONLY valid JSON:
{
  "h1": "Main headline",
  "introduction_angle": "Hook and legal context",
  "sections": [
    {"h2": "Section heading", "key_points": ["point 1", "point 2"], "h3_subsections": ["sub 1"]}
  ],
  "conclusion_points": ["takeaway 1", "takeaway 2"],
  "word_count_target": 1500
}

parameters.jsCode:
const raw = $json.message?.content || $json.text || '';
let articleData = {};
try {
  const c = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  articleData = JSON.parse(c);
} catch(e) {
  throw new Error('Article draft parse failed: ' + e.message);
}

const allowedDomains = [
  'law.cornell.edu', 'justia.com', 'courtlistener.com',
  'federalregister.gov', 'uscourts.gov', 'supremecourt.gov',
  'congress.gov', 'legis.state.*.us'
];

const sources = articleData.sources || [];
const unverified = articleData.unverified_claims || [];

const hallucinated = sources.filter(s => {
  try {
    const host = new URL(s.url).hostname.replace('www.','');
    return !allowedDomains.some(d => {
      const regex = new RegExp(d.replace('*','[a-z]+'));
      return regex.test(host);
    });
  } catch(e) {
    return true;
  }
});

const needsReview = unverified.length > 0 || hallucinated.length > 0;
const topicData = $('Select Approved Topic').item.json;

return [{
  json: {
    topicId: topicData.topic_id || topicData.id,
    topicTitle: topicData.title_idea || topicData.title,
    primaryKeyword: topicData.primary_keyword || topicData.keyword,
    targetState: topicData.target_state,
    practiceArea: topicData.practice_area,
    articleHtml: articleData.article_html || '',
    sources: sources,
    unverifiedClaims: unverified,
    hallucinatedCitations: hallucinated,
    requiresHumanReview: needsReview,
    reviewReason: needsReview
      ? `${unverified.length} unverified claim(s), ${hallucinated.length} citation issue(s)`
      : 'PASSED — All primary citations verified'
  }
}];

parameters.prompt:
=You are an SEO director for common-law.ai.

Generate SEO metadata and 5 FAQ items for:
- Topic: "{{ $json.topicTitle }}"
- Primary Keyword: "{{ $json.primaryKeyword }}"
- Jurisdiction: {{ $json.targetState }}
- Practice Area: {{ $json.practiceArea }}

Return ONLY valid JSON:
{
  "seo_title": "SEO title under 60 chars with keyword",
  "meta_description": "Compelling meta description under 155 chars",
  "slug": "url-friendly-slug",
  "excerpt": "2-sentence executive summary",
  "faq_items": [
    {"question": "Common legal question?", "answer": "Clear, precise answer."}
  ]
}

parameters.jsCode:
const validation = $('Validate Facts and Citations').item.json;
const seoRaw = $json.message?.content || $json.text || '';
let seoData = {};
try {
  seoData = JSON.parse(seoRaw.replace(/```json/g,'').replace(/```/g,'').trim());
} catch(e) {}

const livePosts = $('Fetch Site Posts for Linking').all().filter(p => p.json.id).map(p => ({
  id: p.json.id,
  title: p.json.title?.rendered || '',
  url: p.json.link || '',
  slug: p.json.slug || ''
}));

const state = validation.targetState || 'your state';
const practice = validation.practiceArea || 'legal';
const baseUrl = process.env.WORDPRESS_BASE_URL || 'https://common-law.ai';
const ctaUrl = `${baseUrl}/attorneys/?state=${encodeURIComponent(state.toLowerCase())}&practice=${encodeURIComponent(practice.toLowerCase().replace(/\s+/g,'-'))}`;

const related = livePosts.filter(p => {
  const t = p.title.toLowerCase();
  return t.includes(practice.toLowerCase()) || t.includes(state.toLowerCase());
}).slice(0,3);

const relatedHtml = related.length > 0 ?
  `<div class='commonlaw-related' style='margin:32px 0;padding:20px;background:#f8fafc;border-radius:8px;border-left:4px solid #3b82f6;'><h3>Related Legal Guides</h3><ul>${related.map(p=>`<li><a href='${p.url}'>${p.title}</a></li>`).join('')}</ul></div>` : '';

const ctaHtml = `<div class='commonlaw-cta' style='margin:40px 0;padding:28px;background:linear-gradient(135deg,#1e293b,#0f172a);border-radius:12px;color:#fff;text-align:center;'><h3 style='color:#f8fafc;font-size:22px;margin-bottom:8px;'>Need a ${state} ${practice} Attorney?</h3><p style='color:#cbd5e1;margin-bottom:20px;'>Browse verified attorneys in ${state} who specialize in ${practice}.</p><a href='${ctaUrl}' style='display:inline-block;background:#2563eb;color:#fff;padding:12px 28px;border-radius:8px;text-decoration:none;font-weight:600;'>Find a ${state} Attorney &rarr;</a></div>`;

const disclaimerHtml = `<div class='commonlaw-disclaimer' style='margin-top:36px;padding:16px 20px;background:#f1f5f9;border-left:4px solid #64748b;font-size:13px;color:#475569;font-style:italic;'><strong>Legal Disclaimer:</strong> This article is for informational and educational purposes only and does not constitute formal legal advice. No attorney-client relationship is created by accessing this content. Always consult a qualified attorney licensed in your jurisdiction for guidance on specific legal matters.</div>`;

const sources = validation.sources || [];
const sourcesHtml = sources.length > 0 ?
  `<div class='commonlaw-sources' style='margin-top:32px;border-top:1px solid #e2e8f0;padding-top:20px;'><h2>Sources &amp; References</h2><ul style='font-size:14px;'>${sources.map(s=>`<li><a href='${s.url}' target='_blank' rel='noopener nofollow'>${s.title}</a>${s.cited_for?' — '+s.cited_for:''}</li>`).join('')}</ul></div>` : '';

const faqItems = seoData.faq_items || [];
const faqHtml = faqItems.length > 0 ?
  `<div class='commonlaw-faq' style='margin-top:36px;'><h2>Frequently Asked Questions</h2>${faqItems.map(f=>`<div style='margin-bottom:20px;'><h3>${f.question}</h3><p>${f.answer}</p></div>`).join('')}</div>` : '';

const articleSchema = {
  '@context': 'https://schema.org',
  '@type': 'Article',
  'headline': seoData.seo_title || validation.topicTitle,
  'description': seoData.meta_description || '',
  'mainEntityOfPage': `${baseUrl}/${seoData.slug || 'legal-guide'}/`,
  'author': {'@type': 'Organization', 'name': 'Common-Law.ai Editorial Team'},
  'publisher': {'@type': 'Organization', 'name': 'Common-Law.ai', 'url': baseUrl},
  'datePublished': new Date().toISOString().split('T')[0]
};

const faqSchema = faqItems.length > 0 ? {
  '@context': 'https://schema.org',
  '@type': 'FAQPage',
  'mainEntity': faqItems.map(f => ({
    '@type': 'Question',
    'name': f.question,
    'acceptedAnswer': {'@type': 'Answer', 'text': f.answer}
  }))
} : null;

const fullHtml = [
  validation.articleHtml,
  relatedHtml, faqHtml, sourcesHtml, ctaHtml, disclaimerHtml,
  `<script type='application/ld+json'>${JSON.stringify(articleSchema)}</script>`,
  faqSchema ? `<script type='application/ld+json'>${JSON.stringify(faqSchema)}</script>` : ''
].filter(Boolean).join('\n');

return [{
  json: {
    ...validation,
    seoTitle: seoData.seo_title || validation.topicTitle,
    metaDescription: seoData.meta_description || '',
    slug: seoData.slug || (validation.topicTitle||'').toLowerCase().replace(/[^a-z0-9]+/g,'-'),
    excerpt: seoData.excerpt || '',
    faqItems: faqItems,
    articleSchema,
    faqSchema,
    categories: [validation.targetState, validation.practiceArea].filter(Boolean),
    tags: [validation.primaryKeyword, 'common law', validation.practiceArea, validation.targetState].filter(Boolean),
    contentHtml: fullHtml,
    imagePrompt: `Professional legal consultation in ${state}, modern law office, editorial photography, cinematic lighting, 1600x900, no text`,
    imageAltText: `${validation.topicTitle} - Legal Guide`,
    wpForceDraft: validation.requiresHumanReview
  }
}];

